/**
 * @suppress
 */
public object FfiConverterTypeTorrentRuntimeBridge: FfiConverter<TorrentRuntimeBridge, Pointer> {

    override fun lower(value: TorrentRuntimeBridge): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TorrentRuntimeBridge {
        return TorrentRuntimeBridge(value)
    }

    override fun read(buf: ByteBuffer): TorrentRuntimeBridge {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TorrentRuntimeBridge) = 8UL

    override fun write(value: TorrentRuntimeBridge, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}





sealed class CoreException: kotlin.Exception() {

    class InvalidInput(
        ) : CoreException() {
        override val message
            get() = ""
    }

    class Bridge(
        ) : CoreException() {
        override val message
            get() = ""
    }

    class SubtitleProjectionUnsupported(
        ) : CoreException() {
        override val message
            get() = ""
    }


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {


        return when(buf.getInt()) {
            1 -> CoreException.InvalidInput()
            2 -> CoreException.Bridge()
            3 -> CoreException.SubtitleProjectionUnsupported()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.Bridge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is CoreException.SubtitleProjectionUnsupported -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.InvalidInput -> {
                buf.putInt(1)
                Unit
            }
            is CoreException.Bridge -> {
                buf.putInt(2)
                Unit
            }
            is CoreException.SubtitleProjectionUnsupported -> {
                buf.putInt(3)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUInt: FfiConverterRustBuffer<kotlin.UInt?> {
    override fun read(buf: ByteBuffer): kotlin.UInt? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUInt.read(buf)
    }

    override fun allocationSize(value: kotlin.UInt?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UInt?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUInt.write(value, buf)
        }
    }
}




